"(function() {
    var originalConsole = {
        log: console.log,
        warn: console.warn,
        error: console.error,
        info: console.info,
        debug: console.debug
    };

    function sendToNative(level, args) {
        try {
            var message = Array.prototype.slice.call(args).map(function(arg) {
                if (typeof arg === 'object') {
                    try {
                        return JSON.stringify(arg);
                    } catch(e) {
                        return String(arg);
                    }
                }
                return String(arg);
            }).join(' ');

            var error = new Error();
            var stack = error.stack || '';
            var lines = stack.split('\n');
            var source = '';
            var line = 0;

            if (lines.length > 2) {
                var match = lines[2].match(/at\s+(.+?):(\d+):(\d+)/);
                if (match) {
                    source = match[1];
                    line = parseInt(match[2]);
                }
            }

            window.webkit.messageHandlers.consoleLog.postMessage({
                level: level,
                message: message,
                source: source,
                line: line
            });
        } catch(e) {
            // 静默失败
        }
    }

    console.log = function() {
        originalConsole.log.apply(console, arguments);
        sendToNative('log', arguments);
    };

    console.warn = function() {
        originalConsole.warn.apply(console, arguments);
        sendToNative('warn', arguments);
    };

    console.error = function() {
        originalConsole.error.apply(console, arguments);
        sendToNative('error', arguments);
    };

    console.info = function() {
        originalConsole.info.apply(console, arguments);
        sendToNative('info', arguments);
    };

    console.debug = function() {
        originalConsole.debug.apply(console, arguments);
        sendToNative('debug', arguments);
    };
})();"

